import{_ as s,C as o,o as n,c as r,a2 as a,E as i}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/scaffold-a-story-how-read.webp",h="/guide/media/scaffold-a-story-start-new.webp",c="/guide/media/scaffold-a-story-work-fix.webp",l="/guide/media/scaffold-a-story-word.webp",p="/guide/media/scaffold-a-story-scrivener.webp",g="/guide/media/scaffold-a-story-fountain.webp",E=JSON.parse('{"title":"Scaffold a story folder","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scaffold-a-story.md","filePath":"guide/scaffold-a-story.md","lastUpdated":1791677002000}'),u={name:"guide/scaffold-a-story.md"};function y(m,e,f,k,w,b){const t=o("Clip");return n(),r("div",null,[e[0]||(e[0]=a('<h1 id="scaffold-a-story-folder" tabindex="-1">Scaffold a story folder <a class="header-anchor" href="#scaffold-a-story-folder" aria-label="Permalink to &quot;Scaffold a story folder&quot;">​</a></h1><p>Leathercase reads a story from a folder of your own files. It does not ask you to change how you write, but the shape of that folder decides what the views can show: which notes are the cast, which are scenes, and which are work about the story. This page walks through building a folder Leathercase reads well, step by step, first in Markdown and then in the other formats it reads: a Word manuscript, a Scrivener project and a Fountain screenplay.</p><p>Everything here is a convention, not a requirement. A story you have already written in your own shape can be declared as it is, and <a href="/guide/guide/declare-a-story">Declaring a story</a> lets you say what each folder holds. The shape below is the one that needs the fewest answers.</p><p><img src="'+d+`" alt="The Lamp at Ferrol open in Leathercase, its folder shape shown on How this story is read" width="1130" height="852" loading="lazy"></p><h2 id="the-shape-at-a-glance" tabindex="-1">The shape at a glance <a class="header-anchor" href="#the-shape-at-a-glance" aria-label="Permalink to &quot;The shape at a glance&quot;">​</a></h2><p>The sample story, The Lamp at Ferrol, is laid out the way Leathercase reads best:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The Lamp at Ferrol/</span></span>
<span class="line"><span>├── The Lamp at Ferrol.md        the story&#39;s note: its target, deadline, premise</span></span>
<span class="line"><span>├── Characters/                  one note per person; the folder types them</span></span>
<span class="line"><span>│   ├── Nora Vidal.md            aliases: [Nora]</span></span>
<span class="line"><span>│   └── Bastian Kell.md</span></span>
<span class="line"><span>├── Places/                      one note per place</span></span>
<span class="line"><span>│   └── Ferrol Point.md</span></span>
<span class="line"><span>├── Items/                       objects that carry continuity</span></span>
<span class="line"><span>├── Factions/                    groups, houses, guilds</span></span>
<span class="line"><span>├── Events/                      things that happened, often before page one</span></span>
<span class="line"><span>├── Act I - The Dark Lamp/       chapters: plain notes with headings</span></span>
<span class="line"><span>│   ├── 01 The Night the Lamp Went Out.md     each # heading is a scene</span></span>
<span class="line"><span>│   └── 02 The Ledger.md</span></span>
<span class="line"><span>├── Act II - Salvage/</span></span>
<span class="line"><span>├── Act III - Light/</span></span>
<span class="line"><span>├── _Work/                       memos and research, left out of the story</span></span>
<span class="line"><span>│   └── Research - Fresnel lenses.md</span></span>
<span class="line"><span>└── suite/                       Leathercase&#39;s own files for this story</span></span></code></pre></div><p>You write everything in this tree except <code>suite/</code>. Leathercase writes only into <code>suite/</code> folders and its own cards; it reads your notes and never changes them.</p><p>The sample also keeps two older files at its root, <code>Story threads.md</code> and <code>Outline.md</code>, in the shape the Creative Writer plugin wrote them, to show how such files are read: the threads are read from <code>Story threads.md</code> until Leathercase&#39;s own <code>suite/StoryThreads.md</code> exists, and the outline&#39;s planned scenes were carried into <code>suite/PlotGrid.md</code> once. See <a href="/guide/reference/suite-files#older-files-it-still-reads">Files Leathercase writes</a>.</p><h2 id="step-1-make-the-story-folder" tabindex="-1">Step 1: make the story folder <a class="header-anchor" href="#step-1-make-the-story-folder" aria-label="Permalink to &quot;Step 1: make the story folder&quot;">​</a></h2><p>Make one folder per story inside your writing home (the folder you pointed Leathercase at; see <a href="/guide/guide/homes-and-stories">Homes and stories</a>). Name it for the story. The folder is the structure: there is no index note, no database and no project file to keep in step.</p><p>You can let Leathercase make the folder for you. In the sidebar, click <strong>Declare a story</strong> (the + beside <strong>Stories</strong>), choose <strong>Start a new story</strong>, and give it a working title. Leathercase makes a folder of that name in the home and declares it. Leave <strong>Folders for the cast and the world</strong> ticked and it also makes empty <code>Characters</code>, <code>Places</code>, <code>Items</code>, <code>Factions</code> and <code>Events</code> folders, named in the story&#39;s language. It makes folders, never files: the prose is yours to begin.</p><p><img src="`+h+'" alt="The Declare a story page with Start a new story chosen and Folders for the cast and the world ticked" width="1130" height="852" loading="lazy"></p>',13)),i(t,{name:"scaffold-a-story-start-new",caption:"Starting a new story: a working title, the folders for the cast and the world, and the story declared"}),e[1]||(e[1]=a(`<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A folder whose name is only dots or spaces cannot be a story folder, and the characters <code>\\ / : * ? &quot; &lt; &gt; |</code> are taken out of a title before it becomes a folder name, so the same story opens on every system.</p></div><h2 id="step-2-write-the-story-s-note" tabindex="-1">Step 2: write the story&#39;s note <a class="header-anchor" href="#step-2-write-the-story-s-note" aria-label="Permalink to &quot;Step 2: write the story&#39;s note&quot;">​</a></h2><p>Put a note in the story&#39;s folder named for the story, such as <code>The Lamp at Ferrol.md</code>. Its front matter is where a story&#39;s settings can start. When you declare the story, Leathercase reads these keys once and copies them into the story&#39;s settings, so nothing is typed twice:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">story</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">writing-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">The Lamp at Ferrol</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">writing-target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">writing-daily</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">writing-deadline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-12-31&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">writing-stage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">drafting</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">writing-premise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A keeper&#39;s daughter must relight the lamp her father let go dark.&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>What Leathercase does with it</th></tr></thead><tbody><tr><td><code>story: true</code> or <code>writing-target</code></td><td>Marks this note as the story&#39;s note: about the story, never a scene of it</td></tr><tr><td><code>writing-name</code></td><td>The name offered when you declare the story, instead of the folder&#39;s name</td></tr><tr><td><code>writing-target</code></td><td>The word target, for the Desk&#39;s pace</td></tr><tr><td><code>writing-deadline</code></td><td>The deadline, written <code>&quot;YYYY-MM-DD&quot;</code> in quotes</td></tr><tr><td><code>writing-daily</code> (or <code>writing-goal</code>)</td><td>A number of words a day</td></tr><tr><td><code>writing-days</code></td><td>Which days you write: a list such as <code>[mon, tue, wed]</code>, or <code>weekdays</code>, <code>weekends</code>, <code>daily</code></td></tr><tr><td><code>story-ignore</code></td><td>Names the Graph must not take for characters</td></tr><tr><td><code>plot-pov</code>, <code>plot-time</code>, <code>plot-theme</code>, <code>plot-beats</code></td><td>Which threads the plot grid uses as columns</td></tr><tr><td><code>dialogue</code>, <code>thoughts</code>, <code>speakers</code></td><td>How the dialogue lens reads speech and thought</td></tr><tr><td><code>writing-stage</code></td><td>The stage on the story&#39;s card on the Writer Board: <code>development</code>, <code>drafting</code>, <code>revising</code>, <code>finished</code> or <code>shelved</code>. Without it the card says <strong>drafting</strong> once there is prose and <strong>finished</strong> once the target is met (<strong>idea</strong> is the state of a card with no story yet, never a value to write)</td></tr><tr><td><code>writing-premise</code></td><td>The premise on that card</td></tr><tr><td><code>writing-idea</code></td><td>A link, <code>&quot;[[A lamp that lies]]&quot;</code>, to the premise card the story grew from</td></tr><tr><td><code>writing-voice</code></td><td>A link, <code>&quot;[[The ledger voice]]&quot;</code>, to the voice card on the Writer Board</td></tr></tbody></table><p>The settings keys are read when you declare the story. After that the story&#39;s settings are kept in its <code>suite/</code> folder and you change them in <a href="/guide/guide/story-settings">Story settings</a>; editing the note later does not change them. The Writer Board keys (<code>writing-stage</code>, <code>writing-premise</code>, <code>writing-idea</code>, <code>writing-voice</code>) are read every time the board is drawn. The full list is in <a href="/guide/reference/front-matter">Front matter</a>.</p><p>The note is optional. A story with no story&#39;s note reads the same; you set its target and deadline in Story settings or from the Desk.</p><h2 id="step-3-give-each-person-place-and-thing-a-note" tabindex="-1">Step 3: give each person, place and thing a note <a class="header-anchor" href="#step-3-give-each-person-place-and-thing-a-note" aria-label="Permalink to &quot;Step 3: give each person, place and thing a note&quot;">​</a></h2><p>Make one note per character in <code>Characters/</code>, one per place in <code>Places/</code>, and so on. These typed notes are the cast: they become the names in the <a href="/guide/guide/graph">Graph</a>, the rows of <a href="/guide/guide/characters">Characters</a> and the cast on the <a href="/guide/guide/plot-grid">Plot grid</a>. A typed note is never read as a scene, so a character sheet full of prose does not turn into a chapter.</p><p>A note is typed in one of two ways:</p><ul><li><strong>By its folder.</strong> A note in a folder named for its kind takes that kind. The nearest folder wins.</li><li><strong>By its front matter.</strong> <code>type: character</code> (or <code>kind:</code> or <code>entity:</code>) types the note wherever it sits. When the folder and the front matter disagree, the front matter wins, and <strong>How this story is read</strong> points out the disagreement.</li></ul><table tabindex="0"><thead><tr><th>Kind</th><th>Folder names Leathercase reads</th><th><code>type:</code> words</th></tr></thead><tbody><tr><td>Character</td><td><code>Characters</code>, <code>People</code>, <code>Cast</code>, <code>Dramatis personae</code>, <code>NPCs</code></td><td><code>character</code>, <code>person</code>, <code>people</code>, <code>npc</code>, <code>protagonist</code>, <code>antagonist</code></td></tr><tr><td>Place</td><td><code>Places</code>, <code>Locations</code>, <code>Settings</code>, <code>World</code>, <code>Worldbuilding</code>, <code>Geography</code>, <code>Maps</code></td><td><code>place</code>, <code>location</code>, <code>setting</code>, <code>world</code>, <code>region</code>, <code>city</code></td></tr><tr><td>Item</td><td><code>Items</code>, <code>Objects</code>, <code>Artifacts</code>, <code>Artefacts</code></td><td><code>item</code>, <code>object</code>, <code>artifact</code>, <code>artefact</code></td></tr><tr><td>Faction</td><td><code>Factions</code>, <code>Organisations</code>, <code>Organizations</code>, <code>Houses</code>, <code>Groups</code></td><td><code>faction</code>, <code>organisation</code>, <code>organization</code>, <code>house</code>, <code>group</code></td></tr><tr><td>Event</td><td><code>Events</code>, <code>Timeline</code>, <code>History</code></td><td><code>event</code></td></tr></tbody></table><p>Folder names are read without regard to case, most of them singular or plural, and in the six languages Leathercase recognises in your files (<a href="/guide/reference/languages#folder-names-in-every-language">Languages</a>), so <code>Personagens/</code> and <code>Lugares/</code> work as well as <code>Characters/</code> and <code>Places/</code>.</p><p>The note&#39;s name is the character&#39;s name: <code>Nora Vidal.md</code> is Nora Vidal. A character note can carry more than that:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">character</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">aliases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Nora</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pronouns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">she/her</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#1f5f7a&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">accent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">watch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">accent-never</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">salvage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>aliases</code> (or <code>alias</code>)</td><td>Other names the prose uses for this note</td></tr><tr><td><code>name</code></td><td>One more other name</td></tr><tr><td><code>pronouns</code> (or <code>pronoun</code>)</td><td>The pronoun Leathercase reads back to this character: <code>she/her</code> or <code>he/him</code></td></tr><tr><td><code>gender</code> (or <code>sex</code>)</td><td>The same, said another way when there is no <code>pronouns:</code>: <code>female</code>, <code>f</code>, <code>woman</code>, <code>male</code>, <code>m</code>, <code>man</code></td></tr><tr><td><code>color</code> (or <code>colour</code>)</td><td>The character&#39;s colour, six hex digits in quotes. The accents lens marks this character&#39;s words in it; the dialogue lens does not colour lines by speaker (see <a href="/guide/guide/lenses#accents">Lenses and style checks</a>)</td></tr><tr><td><code>accent</code>, <code>accent-never</code></td><td>Words this character uses and never says, for the accents lens</td></tr></tbody></table><p>A <code>## Relationships</code> section in a typed note is read as ties in the Graph, one per line, with a word and no type: <code>- [[Inés Roca]] — friend</code>. Ties with a type you draw in the Graph itself, into <code>Graph/Ties.md</code> in the story&#39;s <code>suite/</code> folder. A note of a kind of your own, such as a symbol, can say what it stands for the same way, under a <code>## Stands for</code> heading: <code>- [[Nora Vidal]] — the truth she will not leave</code>. Leathercase reads both headings and never writes them.</p><h3 id="other-names-for-the-same-person" tabindex="-1">Other names for the same person <a class="header-anchor" href="#other-names-for-the-same-person" aria-label="Permalink to &quot;Other names for the same person&quot;">​</a></h3><p><code>aliases: [Nora]</code> tells Leathercase that Nora is Nora Vidal. You often need no alias at all: a first name or a surname that only one note has finds that note on its own. A name two notes share, such as Vidal when there are three Vidals, finds neither until you give it as an alias of one.</p><p>You can also confirm an alias in the Graph. Leathercase keeps what you confirm in Story settings and never writes it into your note.</p><h3 id="names-without-a-note" tabindex="-1">Names without a note <a class="header-anchor" href="#names-without-a-note" aria-label="Permalink to &quot;Names without a note&quot;">​</a></h3><p>A name that recurs three times in the prose with no note of its own shows in the Graph as a name without a note. Pin it and say it is another name for someone (<strong>Alias of</strong>), or <strong>Not a name</strong>; both are kept in Story settings, and the Graph&#39;s <strong>Names you settled</strong> can undo them. To give it a note instead, use the fix on <strong>How this story is read</strong> (<strong>Make a character note</strong> or <strong>Make a place note</strong>): Leathercase makes a note for it in the story&#39;s <code>suite/</code> folder, a note it owns and you may fill.</p><p>You can make a note for the story from anywhere too: type <code>character: Inés Roca</code> in the find field. See <a href="/guide/guide/find">Find, open and make</a>.</p><h2 id="step-4-write-acts-and-chapters-with-headings-as-scenes" tabindex="-1">Step 4: write acts and chapters, with headings as scenes <a class="header-anchor" href="#step-4-write-acts-and-chapters-with-headings-as-scenes" aria-label="Permalink to &quot;Step 4: write acts and chapters, with headings as scenes&quot;">​</a></h2><p>Only files declared as the story&#39;s prose make scenes. When you declare a story you tick its files and say what each folder holds; where nothing claims a folder, Leathercase proposes <strong>The story&#39;s prose</strong> for it, and you can change that. A typed note, a note left out and the story&#39;s note are never prose, and a file nothing claims waits, unsorted, on <strong>How this story is read</strong> until you say what it is (see <a href="/guide/guide/declare-a-story#the-seven-roles">Declaring a story</a>). Put chapters in folders for acts, or straight in the story&#39;s folder, as you like, and let the declaration read them as prose. A folder named <code>Chapters</code>, <code>Manuscript</code>, <code>Scenes</code>, <code>Draft</code> or <code>Drafts</code> is read as prose by its name alone.</p><p><strong>Headings make scenes.</strong> Each heading with prose under it is a scene: a row on the plot grid, a slot on the threads chart, a section in the manuscript. Any level of heading works.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># The cottage</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The lamp went out at ten past two, and Nora knew it before she was awake.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># The tower</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The door at the foot of the tower was open.</span></span></code></pre></div><ul><li>A note with prose and no heading is one scene. A long one, past about 1,500 words, is pointed out on <strong>How this story is read</strong> as a chapter you may want to split.</li><li>A heading with no prose under it is a scene planned, not written yet.</li><li>Scenes split only at headings, never at <code>---</code>, <code>***</code> or blank lines. If you mark scene breaks with a line of asterisks today, give each scene a heading and the grid gets a row for it.</li></ul><p><strong>Order comes from the path.</strong> Notes are read in path order, with numbers read as numbers (<code>Chapter 2</code> before <code>Chapter 10</code>), so <code>Act I - The Dark Lamp/01 The Night the Lamp Went Out.md</code> comes before <code>Act II - Salvage/04 Kell&#39;s Offer.md</code>. Number the chapters to keep them in order; the manuscript drops a leading number and separator (<code>01 </code>, <code>03. </code>, <code>2-</code>) from the name it shows. A <code>story-order: 3</code> in a note&#39;s front matter orders it by that number instead: notes with a number come first, by number, and the rest follow by path.</p><p><strong>Keeping a note off the manuscript.</strong> <code>manuscript: false</code> in a note&#39;s front matter keeps it off the manuscript page while it stays in the other views. The sample&#39;s story&#39;s note carries it.</p><p><strong>Comments stay yours.</strong> <code>%% a comment %%</code> in a note is never counted as words and never reaches an export. A comment opening with a word and a colon, <code>%% TODO: the rhythm needs to be felt %%</code>, is a tagged comment Leathercase lists. See <a href="/guide/guide/comments">Comments and word lists</a>.</p><div class="info custom-block"><p class="custom-block-title">A note added after you declare</p><p>When you declare a story, Leathercase writes down which files it read as prose. A file you add later in a folder declared as prose, or in the story&#39;s own folder of a story you started in Leathercase, is read as prose. A file added somewhere nothing claims waits, unsorted, on <strong>How this story is read</strong>, until you say what it is. This keeps a stray memo from turning into a scene.</p></div><h2 id="step-5-keep-work-about-the-story-apart" tabindex="-1">Step 5: keep work about the story apart <a class="header-anchor" href="#step-5-keep-work-about-the-story-apart" aria-label="Permalink to &quot;Step 5: keep work about the story apart&quot;">​</a></h2><p>Memos, research, review notes and transcripts talk about the cast in ways that are not scenes. Read as story, they would put characters in scenes that do not exist. Keep them in a folder of their own, such as <code>_Work/</code>, and leave that folder out in one of two ways:</p><ul><li><strong>With an ignore pattern.</strong> In <a href="/guide/guide/story-settings">Story settings</a>, open <strong>Advanced: the patterns</strong> and add <code>_Work/**</code> under <strong>Files to leave out, one pattern per line</strong>. Every note under <code>_Work/</code> leaves the Graph, the grid, the threads and the manuscript. This is the way that needs no change to your notes.</li><li><strong>With a line of front matter.</strong> <code>creative-writer: false</code> in a note&#39;s front matter leaves that one note out. This is the line the Creative Writer plugin for Obsidian taught; Leathercase honours it, so notes written for the plugin need nothing new.</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">creative-writer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><p>A folder named like work about the story (<code>_Work</code>, any folder starting with <code>_</code>, <code>Memos</code>, <code>Research</code>, <code>Reviews</code>, <code>Archive</code>, <code>Templates</code>, <code>Trash</code>, and the same words in the other languages Leathercase reads) whose notes are being read as scenes is pointed out on <strong>How this story is read</strong>, with a fix that adds the ignore pattern for you.</p><p>Some folder names also say what their notes are without any help: <code>Research/</code> and <code>Sources/</code> hold research, <code>Outline/</code> and <code>Synopsis/</code> hold plans, <code>Cuts/</code>, <code>Outtakes/</code> and <code>Trash/</code> hold scraps. These are read, but never as scenes.</p><p><img src="`+c+`" alt="How this story is read showing a _Work folder read as story, with the fix that leaves it out" width="730" height="297" loading="lazy"></p><h2 id="step-6-let-leathercase-keep-its-own-files" tabindex="-1">Step 6: let Leathercase keep its own files <a class="header-anchor" href="#step-6-let-leathercase-keep-its-own-files" aria-label="Permalink to &quot;Step 6: let Leathercase keep its own files&quot;">​</a></h2><p>Each story gets a <code>suite/</code> folder for what Leathercase writes for it: the threads in <code>StoryThreads.md</code>, the plot grid&#39;s rows in <code>PlotGrid.md</code>, comments, the beat board&#39;s cards and the notes it makes for names. The home gets one too, at its root, with <code>Suite.md</code>, and the Writer Board&#39;s cards go in <code>Writer/</code>. These are small files you can read without Leathercase. They are never read as prose, and you do not need to make them. See <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="before-there-are-chapters" tabindex="-1">Before there are chapters <a class="header-anchor" href="#before-there-are-chapters" aria-label="Permalink to &quot;Before there are chapters&quot;">​</a></h2><p>A story with no draft yet still has a plot grid. Leathercase makes the grid&#39;s file, <code>PlotGrid.md</code> in the story&#39;s <code>suite/</code> folder, the first time it reads the story, even when there is no prose yet. <strong>New scene</strong> on the plot grid (or <strong>Plan a scene</strong> in its <strong>Rows</strong> section, or a card sent to the grid from the <a href="/guide/guide/beat-board">Beat board</a>) writes a planned scene into that file: <code>#</code> for an act, <code>##</code> for a chapter, <code>###</code> for a scene. The grid shows each planned scene as a row with no prose. When you later write the scene in your own notes, the grid offers to link the planned row to it (<strong>This is a scene I wrote…</strong>); see <a href="/guide/guide/plot-grid#linking-a-planned-row-to-a-written-scene">Plot grid</a>.</p><p>An <code>Outline.md</code> kept by the Creative Writer plugin, in the story&#39;s folder, is read once: its planned scenes are carried into <code>PlotGrid.md</code> when that file is first made. Leathercase never writes <code>Outline.md</code>.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Act III - Light</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 11 The Inquest</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### The courtroom</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### The quay</span></span></code></pre></div><p>You can also start from cards: choose <strong>Start from ideas</strong> on the Declare a story page and work on the <a href="/guide/guide/writer-board">Writer Board</a> first. The story&#39;s folder comes later.</p><h2 id="a-smaller-shape-for-a-short-story" tabindex="-1">A smaller shape, for a short story <a class="header-anchor" href="#a-smaller-shape-for-a-short-story" aria-label="Permalink to &quot;A smaller shape, for a short story&quot;">​</a></h2><p>A short story does not need the folders:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The Bear Hunt/</span></span>
<span class="line"><span>├── Draft.md           the whole draft, one # heading per scene</span></span>
<span class="line"><span>├── Vitaliy.md         type: character</span></span>
<span class="line"><span>├── Lee.md             type: character</span></span>
<span class="line"><span>├── Tikka T3x.md       type: item, aliases: [Tikka, the rifle]</span></span>
<span class="line"><span>└── memos/             left out with the pattern memos/**</span></span></code></pre></div><p>Here the front matter does the typing the folders would have done. Keep the draft in its own note rather than in the story&#39;s note: the story&#39;s note is about the story and is never read as scenes.</p><h2 id="what-the-reading-cannot-do-for-you" tabindex="-1">What the reading cannot do for you <a class="header-anchor" href="#what-the-reading-cannot-do-for-you" aria-label="Permalink to &quot;What the reading cannot do for you&quot;">​</a></h2><ul><li>It splits scenes only at headings. Give each scene a heading.</li><li>It reads she and he back to the nearest name it knows, but not an epithet: it does not know that &quot;the boy&quot; is Zak unless Zak&#39;s note lists <code>the boy</code> as an alias.</li><li>It reads Markdown, Word, Scrivener and Fountain. Other files in the folder, such as images or PDFs, are listed and left alone.</li></ul><p><strong>How this story is read</strong>, in each story&#39;s views, shows what these rules found in your folder, with a fix where something looks off. See <a href="/guide/guide/how-a-story-is-read">How a story is read</a>.</p><h2 id="the-same-idea-in-word" tabindex="-1">The same idea in Word <a class="header-anchor" href="#the-same-idea-in-word" aria-label="Permalink to &quot;The same idea in Word&quot;">​</a></h2><p>Leathercase reads <code>.docx</code> files as notes. A folder of Word chapters is a folder of notes, and the rules above apply to it with two differences: a Word file has no front matter, and scenes come from heading styles.</p><p>The sample&#39;s Word story, The Salt Road, is laid out like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The Salt Road/</span></span>
<span class="line"><span>├── Chapters/</span></span>
<span class="line"><span>│   ├── 01 The Tally.docx</span></span>
<span class="line"><span>│   ├── 02 Imbar Wells.docx</span></span>
<span class="line"><span>│   ├── 03 The Red Wind.docx</span></span>
<span class="line"><span>│   └── 04 Kel Asir.docx</span></span>
<span class="line"><span>├── Characters/</span></span>
<span class="line"><span>│   ├── Khaled Amar.docx</span></span>
<span class="line"><span>│   └── Mirela Voss.docx</span></span>
<span class="line"><span>└── Places/</span></span>
<span class="line"><span>    ├── Imbar Wells.docx</span></span>
<span class="line"><span>    └── Tamsalt.docx</span></span></code></pre></div><ul><li><strong>Scenes are headings.</strong> Give each scene a heading in Word&#39;s <strong>Heading 1</strong> style (Heading 2 and lower work too, one level down). A paragraph in bold that looks like a heading is not one; the style is what counts.</li><li><strong>The cast is typed by its folder.</strong> Put each character&#39;s document in <code>Characters/</code>, each place in <code>Places/</code>. Without front matter, the folder is the only way a Word note says what it is, besides what you say when you declare the story.</li><li><strong>Order comes from the file name.</strong> Number the chapters, <code>01 The Tally.docx</code>, as you would Markdown notes.</li><li><strong>The name comes from the properties.</strong> If the chapters carry the story&#39;s title in their document properties (in Word, <strong>File</strong>, <strong>Properties</strong>, <strong>Title</strong>), Leathercase suggests that name when you declare the story.</li><li><strong>What is read.</strong> Headings, paragraphs, italic, bold, block quotes (the Quote and Intense Quote styles), lists and tables. Word&#39;s comments, headers, footers and images are not read.</li></ul><p>Leathercase never writes into a <code>.docx</code>. Keep writing in Word; Leathercase reads each save.</p><p><img src="`+l+`" alt="The Salt Road open on its manuscript, read from Word" width="1130" height="700" loading="lazy"></p><h2 id="the-same-idea-in-scrivener" tabindex="-1">The same idea in Scrivener <a class="header-anchor" href="#the-same-idea-in-scrivener" aria-label="Permalink to &quot;The same idea in Scrivener&quot;">​</a></h2><p>Leathercase reads a Scrivener 3 project (<code>.scriv</code>) as a folder of notes, in binder order. Scrivener 2 projects are read too. Declare the folder that holds the <code>.scriv</code> package, as the sample does with Orchard Hours:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Orchard Hours/</span></span>
<span class="line"><span>└── Orchard Hours.scriv</span></span>
<span class="line"><span>    binder:</span></span>
<span class="line"><span>    ├── Manuscript          (the Draft folder)</span></span>
<span class="line"><span>    │   ├── Friday</span></span>
<span class="line"><span>    │   │   ├── First Light</span></span>
<span class="line"><span>    │   │   └── The Car from London</span></span>
<span class="line"><span>    │   ├── Saturday</span></span>
<span class="line"><span>    │   └── Sunday</span></span>
<span class="line"><span>    ├── Research</span></span>
<span class="line"><span>    │   ├── Characters</span></span>
<span class="line"><span>    │   │   ├── Ruth Ashby</span></span>
<span class="line"><span>    │   │   └── Owen Pryce</span></span>
<span class="line"><span>    │   └── Places</span></span>
<span class="line"><span>    │       └── Hollins Farm</span></span>
<span class="line"><span>    └── Trash</span></span></code></pre></div><ul><li><strong>The Draft is the story.</strong> Every text document in the Draft folder, whatever you titled it, is read in binder order. A document with no heading in it is one scene, named by its binder title. Folders in the Draft are chapters or parts.</li><li><strong>Research holds the cast.</strong> Folders in Research keep their titles, so a <code>Characters</code> folder in Research is a folder of characters and a <code>Places</code> folder is a folder of places, typed as in Markdown.</li><li><strong>The Trash is left out.</strong> A document you moved to the Trash never reaches the views.</li><li><strong>Nothing is written.</strong> The project is read and never changed, so it is safe to have it open in Scrivener at the same time.</li></ul><p><img src="`+p+`" alt="Orchard Hours open in Leathercase, read from Scrivener" width="1130" height="562" loading="lazy"></p><h2 id="the-same-idea-in-fountain" tabindex="-1">The same idea in Fountain <a class="header-anchor" href="#the-same-idea-in-fountain" aria-label="Permalink to &quot;The same idea in Fountain&quot;">​</a></h2><p>Leathercase reads a Fountain screenplay (<code>.fountain</code>) as one story. The structure lives inside the file, not in folders:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Title: The Night Sleeper     on the title page: the name Leathercase suggests</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ACT ONE                    a section: an act, read as a scene of its own level</span></span>
<span class="line"><span>= A pickpocket boards...     a synopsis</span></span>
<span class="line"><span>EXT. CENTRAL STATION - PLATFORM 9 - NIGHT     a slugline: a scene, and a place</span></span>
<span class="line"><span>JUNO                         a cue: a character</span></span></code></pre></div><ul><li><strong>Sections are acts.</strong> <code>#</code> sections are scenes at their depth: <code>#</code> an act, <code>##</code> a sequence. Sluglines are scenes one level below the deepest section.</li><li><strong>Sluglines name the places.</strong> <code>INT. KOVÁCS HOUSE - KITCHEN - NIGHT</code> is the place Kovács House - Kitchen: the prefix and the time of day are not part of the name.</li><li><strong>Cues name the cast.</strong> <code>ANNA (V.O.)</code> is Anna: extensions and the dual-dialogue mark are not part of the name. Each character and place is declared once, the first time it appears, and every scene knows who speaks in it.</li><li><strong>Action and speech are the prose.</strong> Notes <code>[[ ]]</code> and boneyard <code>/* */</code> are yours and are not read.</li><li><strong>The title page names the story.</strong> <code>Title:</code> is the name Leathercase suggests when you declare it.</li></ul><p>A screenplay is always read as prose, wherever it sits in the folder. You can still keep character notes beside it, in Markdown, in a <code>Characters/</code> folder: they type the cast the same way.</p><p><img src="`+g+'" alt="The Night Sleeper open on its plot grid, acts and sluglines as rows" width="1130" height="900" loading="lazy"></p><h2 id="ready-made-note-templates" tabindex="-1">Ready-made note templates <a class="header-anchor" href="#ready-made-note-templates" aria-label="Permalink to &quot;Ready-made note templates&quot;">​</a></h2><p>The <a href="https://github.com/amancioandre/creative-templates" target="_blank" rel="noreferrer">Creative Templates</a> repository holds note templates for Obsidian (and any editor that inserts a file as a template): a story&#39;s note, a character, a location, an item, a faction, an event, a work note and the Writer Board cards. Each one carries properties in the shape this page describes.</p><p>Not every property in those templates is read by Leathercase today; some were written for the Creative Writer plugin. These are the ones Leathercase reads:</p><table tabindex="0"><thead><tr><th>Template</th><th>Properties Leathercase reads</th></tr></thead><tbody><tr><td>Project note (the story&#39;s note)</td><td><code>story</code>, <code>writing-target</code>, <code>writing-daily</code>, <code>writing-deadline</code>, <code>writing-stage</code>, <code>writing-premise</code>, <code>dialogue</code>, <code>thoughts</code>, <code>manuscript</code></td></tr><tr><td>Character</td><td><code>type</code>, <code>aliases</code>, <code>accent</code>, <code>accent-never</code>, and the <code>## Relationships</code> section</td></tr><tr><td>Location, Item, Faction, Event</td><td><code>type</code>, <code>aliases</code></td></tr><tr><td>Work note</td><td><code>creative-writer: false</code></td></tr><tr><td>Writer cards (Premise, Theme, Archetype, Quote, Voice, Reading, Craft, Card)</td><td><code>tags: [writer/…]</code></td></tr></tbody></table><p><code>writing-scope</code> and <code>bad-words</code>, which the templates mention, are not read by Leathercase. Properties such as <code>date</code>, <code>pov</code>, <code>location</code>, <code>characters</code>, <code>title</code>, <code>author</code>, <code>genre</code> or <code>status</code> on a scene are harmless and ignored: the cast of a scene is read from its prose, and chronology is manuscript order.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/declare-a-story">Declaring a story</a></li><li><a href="/guide/guide/how-a-story-is-read">How a story is read</a></li><li><a href="/guide/guide/story-settings">Story settings</a></li><li><a href="/guide/reference/formats">Files Leathercase reads</a></li><li><a href="/guide/reference/front-matter">Front matter</a></li><li><a href="/guide/guide/plot-grid">Plot grid</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/languages">Languages</a></li></ul>',78))])}const T=s(u,[["render",y]]);export{E as __pageData,T as default};
